macro.implementation:
do {
  if ((usbp)->binder != NULL) {
    chSysLockFromISR();
    usbBinderSOFI((usbp)->binder);
    chSysUnlockFromISR();
  }
} while (false)

do {
  /* The callback can disable the endpoint, the state is taken before.*/
  USBInEndpointState *cb_isp = (usbp)->epc[ep]->in_state;

  /* Cleared under lock, a higher priority USB handler can preempt
     this one and update the other bits.*/
  chSysLockFromISR();
  (usbp)->transmitting &= ~(uint16_t)((unsigned)1U << (unsigned)(ep));
  chSysUnlockFromISR();
  if ((usbp)->epc[ep]->in_cb != NULL) {
    (usbp)->epc[ep]->in_cb(usbp, ep);
  }
  chSysLockFromISR();
  chThdResumeI(&cb_isp->thread, MSG_OK);
  chSysUnlockFromISR();
} while (false)

do {
  /* The callback can disable the endpoint, the state and the received
     size are taken before.*/
  USBOutEndpointState *cb_osp = (usbp)->epc[ep]->out_state;
  size_t cb_n = usbGetReceiveTransactionSizeX(usbp, ep);

  /* Cleared under lock, a higher priority USB handler can preempt
     this one and update the other bits.*/
  chSysLockFromISR();
  (usbp)->receiving &= ~(uint16_t)((unsigned)1U << (unsigned)(ep));
  chSysUnlockFromISR();
  if ((usbp)->epc[ep]->out_cb != NULL) {
    (usbp)->epc[ep]->out_cb(usbp, ep);
  }
  chSysLockFromISR();
  chThdResumeI(&cb_osp->thread, (msg_t)cb_n);
  chSysUnlockFromISR();
} while (false)

do {
  /* Cleared under lock, a higher priority USB handler can preempt
     this one and update the other bits.*/
  chSysLockFromISR();
  (usbp)->transmitting &= ~(uint16_t)((unsigned)1U << (unsigned)(ep));
  chSysUnlockFromISR();
  if ((usbp)->epc[ep]->in_cb != NULL) {
    (usbp)->epc[ep]->in_cb(usbp, ep);
  }
} while (false)

do {
  /* Cleared under lock, a higher priority USB handler can preempt
     this one and update the other bits.*/
  chSysLockFromISR();
  (usbp)->receiving &= ~(uint16_t)((unsigned)1U << (unsigned)(ep));
  chSysUnlockFromISR();
  if ((usbp)->epc[ep]->out_cb != NULL) {
    (usbp)->epc[ep]->out_cb(usbp, ep);
  }
} while (false)

objinit.implementation:
self->binder = NULL;
self->info   = NULL;
self->arg    = NULL;
self->next   = NULL;
self->prev   = NULL;

method.implementation:
self = __usbsvc_objinit_impl(self, vmt);
self->info = infop;

return self;

unsigned base;
unsigned limit;

if ((self->info == NULL) || (self->info->if_count == 0U)) {
  return false;
}

base  = (unsigned)self->info->if_base;
limit = base + (unsigned)self->info->if_count;

return ((unsigned)ifn >= base) && ((unsigned)ifn < limit);

objinit.implementation:
self->usbp         = NULL;
self->services     = NULL;
self->service_last = NULL;
self->services_num = 0U;
self->arg          = NULL;

method.implementation:
hal_usb_service_c *servicep;

for (servicep = self->services; servicep != NULL; servicep = servicep->next) {
  usbServiceOnResetI(servicep);
}

hal_usb_service_c *servicep;

for (servicep = self->services; servicep != NULL; servicep = servicep->next) {
  usbServiceOnConfigureI(servicep);
}

hal_usb_service_c *servicep;

for (servicep = self->services; servicep != NULL; servicep = servicep->next) {
  usbServiceOnUnconfigureI(servicep);
}

hal_usb_service_c *servicep;

for (servicep = self->services; servicep != NULL; servicep = servicep->next) {
  usbServiceOnSuspendI(servicep);
}

hal_usb_service_c *servicep;

for (servicep = self->services; servicep != NULL; servicep = servicep->next) {
  usbServiceOnWakeupI(servicep);
}

hal_usb_service_c *servicep;

for (servicep = self->services; servicep != NULL; servicep = servicep->next) {
  usbServiceOnSOFI(servicep);
}

hal_usb_service_c *servicep;

for (servicep = self->services; servicep != NULL; servicep = servicep->next) {
  if (usbServiceOwnsInEndpointX(servicep, ep)) {
    usbServiceOnInI(servicep, ep);
    return;
  }
}

hal_usb_service_c *servicep;

for (servicep = self->services; servicep != NULL; servicep = servicep->next) {
  if (usbServiceOwnsOutEndpointX(servicep, ep)) {
    usbServiceOnOutI(servicep, ep);
    return;
  }
}

hal_usb_service_c *servicep;
const uint8_t *req;

*handledp = false;
req = usbEp0GetRequestX(self->usbp);
switch (req[0] & USB_RTYPE_RECIPIENT_MASK) {
case USB_RTYPE_RECIPIENT_INTERFACE:
  servicep = usbbnd_get_if_owner(self, req[4]);
  break;
case USB_RTYPE_RECIPIENT_ENDPOINT:
  servicep = usbbnd_get_ep_owner(self, (usbep_t)(req[4] & 0x0FU),
                                 (req[4] & 0x80U) != 0U);
  break;
default:
  for (servicep = self->services; servicep != NULL;
       servicep = servicep->next) {
    msg_t msg;
    bool handled;

    handled = false;
    msg = usbServiceSetup(servicep, &handled);
    if ((msg != HAL_RET_SUCCESS) || handled) {
      *handledp = handled;
      return msg;
    }
  }
  return HAL_RET_SUCCESS;
}

if (servicep == NULL) {
  return HAL_RET_SUCCESS;
}

return usbServiceSetup(servicep, handledp);

objinit.implementation:
/* The fields after the base class ones are zeroed, the LLD initializes its
   own fields after this function.*/
memset((uint8_t *)self + offsetof(hal_usb_driver_c, events), 0,
       sizeof (hal_usb_driver_c) - offsetof(hal_usb_driver_c, events));
self->ep0state      = USB_EP0_STP_WAITING;
self->saved_state   = HAL_DRV_STATE_STOP;

method.implementation:
msg_t msg;

chDbgCheck((self != NULL) && (binderp != NULL));

chSysLock();
if ((self->state == USB_SELECTED) ||
    (self->state == USB_ACTIVE) ||
    (self->state == USB_SUSPENDED)) {
  chSysUnlock();
  return HAL_RET_INV_STATE;
}
chDbgAssert(self->binder == NULL, "binder already attached");
chSysUnlock();

msg = usbBinderBind(binderp, self);
if (msg == HAL_RET_SUCCESS) {
  self->binder = binderp;
}

return msg;

hal_usb_binder_c *binderp;

chDbgCheck(self != NULL);

chSysLock();
if ((self->state == USB_SELECTED) ||
    (self->state == USB_ACTIVE) ||
    (self->state == USB_SUSPENDED)) {
  chSysUnlock();
  return HAL_RET_INV_STATE;
}
/* A hardware failure can leave the services configured.*/
usb_unconfigure_services_i(self);
binderp = self->binder;
self->binder = NULL;
chSchRescheduleS();
chSysUnlock();

/* The driver no longer refers to the binder, the unbind hooks are API
   functions and run outside the lock.*/
if (binderp != NULL) {
  usbBinderUnbind(binderp);
}

return HAL_RET_SUCCESS;

chDbgCheck(self != NULL);
chDbgAssert(self->binder != NULL, "no binder");

if (self->state != USB_ERROR) {
  usb_lld_connect_bus(self);
}

chDbgCheckClassI();
chDbgCheck((self != NULL) && (epcp != NULL) &&
             (ep <= (usbep_t)USB_MAX_ENDPOINTS));
if (self->state == USB_ERROR) {
  return;
}
chDbgAssert(self->state == USB_ACTIVE, "invalid state");
chDbgAssert(self->epc[ep] == NULL, "already initialized");

self->epc[ep] = epcp;
if (epcp->in_state != NULL) {
  memset(epcp->in_state, 0, sizeof(USBInEndpointState));
}
if (epcp->out_state != NULL) {
  memset(epcp->out_state, 0, sizeof(USBOutEndpointState));
}

usb_lld_init_endpoint(self, ep);

unsigned i;

chDbgCheckClassI();
chDbgCheck(self != NULL);
if (self->state == USB_ERROR) {
  return;
}
chDbgAssert(self->state == USB_ACTIVE, "invalid state");

self->transmitting &= 1U;
self->receiving    &= 1U;
for (i = 1U; i <= (unsigned)USB_MAX_ENDPOINTS; i++) {
#if USB_USE_SYNCHRONIZATION == TRUE
  if (self->epc[i] != NULL) {
    if (self->epc[i]->in_state != NULL) {
      chThdResumeI(&self->epc[i]->in_state->thread, MSG_RESET);
    }
    if (self->epc[i]->out_state != NULL) {
      chThdResumeI(&self->epc[i]->out_state->thread, MSG_RESET);
    }
  }
#endif
  self->epc[i] = NULL;
}

usb_lld_disable_endpoints(self);

chDbgCheckClassI();
chDbgCheck((self != NULL) && (buf != NULL) &&
             (ep <= (usbep_t)USB_MAX_ENDPOINTS));

usb_lld_read_setup(self, ep, buf);

USBOutEndpointState *osp;

chDbgCheckClassI();
chDbgCheck((self != NULL) && (ep <= (usbep_t)USB_MAX_ENDPOINTS));
if (self->state == USB_ERROR) {
  return;
}
chDbgAssert((self->epc[ep] != NULL) && (self->epc[ep]->out_state != NULL),
              "endpoint not configured");
chDbgAssert((self->receiving &
               (uint16_t)((unsigned)1U << (unsigned)ep)) == 0U,
              "already receiving");

self->receiving |= (uint16_t)((unsigned)1U << (unsigned)ep);
osp = self->epc[ep]->out_state;
osp->rxbuf  = buf;
osp->rxsize = n;
osp->rxcnt  = 0U;
osp->rxpkts = 0U;
#if USB_USE_SYNCHRONIZATION == TRUE
osp->thread = NULL;
#endif

usb_lld_start_out(self, ep);

USBInEndpointState *isp;

chDbgCheckClassI();
chDbgCheck((self != NULL) && (ep <= (usbep_t)USB_MAX_ENDPOINTS));
if (self->state == USB_ERROR) {
  return;
}
chDbgAssert((self->epc[ep] != NULL) && (self->epc[ep]->in_state != NULL),
              "endpoint not configured");
chDbgAssert((self->transmitting &
               (uint16_t)((unsigned)1U << (unsigned)ep)) == 0U,
              "already transmitting");

self->transmitting |= (uint16_t)((unsigned)1U << (unsigned)ep);
isp = self->epc[ep]->in_state;
isp->txbuf  = buf;
isp->txsize = n;
isp->txcnt  = 0U;
isp->txlast = 0U;
#if USB_USE_SYNCHRONIZATION == TRUE
isp->thread = NULL;
#endif

usb_lld_start_in(self, ep);

msg_t msg;

chDbgCheck((self != NULL) && (ep <= (usbep_t)USB_MAX_ENDPOINTS));

chSysLock();
if (self->state == USB_ERROR) {
  chSysUnlock();
  return HAL_RET_HW_FAILURE;
}
if (self->state != USB_ACTIVE) {
  chSysUnlock();
  return MSG_RESET;
}

usbStartReceiveI(self, ep, buf, n);
msg = chThdSuspendTimeoutS(&self->epc[ep]->out_state->thread, TIME_INFINITE);
chSysUnlock();

return msg;

msg_t msg;

chDbgCheck((self != NULL) && (ep <= (usbep_t)USB_MAX_ENDPOINTS));

chSysLock();
if (self->state == USB_ERROR) {
  chSysUnlock();
  return HAL_RET_HW_FAILURE;
}
if (self->state != USB_ACTIVE) {
  chSysUnlock();
  return MSG_RESET;
}

usbStartTransmitI(self, ep, buf, n);
msg = chThdSuspendTimeoutS(&self->epc[ep]->in_state->thread, TIME_INFINITE);
chSysUnlock();

return msg;

method.note:
@p HAL_RET_HW_FAILURE is latched until the application
                stops the driver. Retrying does not recover the controller;
                a worker polling for stop must sleep between retries to let
                the application handle @p USB_FLAGS_HW_FAILURE and call
                @p drvStop().

method.return:
@p MSG_OK if a setup packet is available, @p MSG_RESET
                on cancellation, or @p HAL_RET_HW_FAILURE if the controller
                has failed.

method.implementation:
msg_t msg;

chDbgCheck(self != NULL);

chSysLock();
if (self->state == USB_ERROR) {
  /* The fault handler does not call service hooks, the services are
     unconfigured here, outside any service code.*/
  usb_unconfigure_services_i(self);
  chSchRescheduleS();
  chSysUnlock();
  return HAL_RET_HW_FAILURE;
}
if ((self->state == HAL_DRV_STATE_STOP) ||
    (self->state == HAL_DRV_STATE_STOPPING) ||
    (self->state == HAL_DRV_STATE_UNINIT)) {
  chSysUnlock();
  return MSG_RESET;
}
if (self->ep0reset != 0U) {
  self->ep0reset = 0U;
  chSysUnlock();
  return MSG_RESET;
}
if (self->ep0setup != 0U) {
  self->ep0setup = 0U;
  ep0_take_request_i(self);
  chSysUnlock();
  return MSG_OK;
}

msg = chThdSuspendTimeoutS(&self->ep0thread, TIME_INFINITE);
if (msg == MSG_OK) {
  self->ep0setup = 0U;
  ep0_take_request_i(self);
}
else {
  self->ep0reset = 0U;
  /* The state is checked, not the message: after a restart a stale
     failure must not unconfigure the new session.*/
  if (self->state == USB_ERROR) {
    usb_unconfigure_services_i(self);
    chSchRescheduleS();
  }
}
chSysUnlock();

return msg;

method.note:
A buffer smaller than the data stage announced by the
                request cannot receive it: the request is stalled and
                @p MSG_RESET returned.

method.implementation:
chDbgCheck(self != NULL);

chSysLock();
/* A request replaced by a SETUP, a reset or a stop is not stalled, the
   stall would hit the next request.*/
if (!ep0_is_current_i(self)) {
  chSysUnlock();
  return;
}
usb_lld_stall_in(self, 0);
usb_lld_stall_out(self, 0);
self->receiving &= ~1U;
self->transmitting &= ~1U;
self->ep0n = 0U;
self->ep0endcb = NULL;
self->ep0state = USB_EP0_ERROR;
usb_post_events_i(self, USB_FLAGS_STALLED);
chSysUnlock();

msg_t msg = MSG_OK;
uint16_t type;
uint16_t recipient;
uint16_t request;
const usb_descriptor_t *dp;
const uint8_t *req;
usbep_t ep;
bool in;

chDbgCheck((self != NULL) && (handledp != NULL));

*handledp = false;

if (self->state == USB_ERROR) {
  return HAL_RET_HW_FAILURE;
}

/* The request taken by usbEp0WaitSetup(), a later SETUP does not change
   it. Side effects are applied only while it is still current.*/
req = self->ep0req;
if ((req[0] & USB_RTYPE_TYPE_MASK) != USB_RTYPE_TYPE_STD) {
  return MSG_OK;
}

*handledp = true;
recipient = req[0] & USB_RTYPE_RECIPIENT_MASK;
request = req[1];
type = recipient | (uint16_t)(request << 8U);
ep = req[4] & 0x0FU;
in = (req[4] & 0x80U) != 0U;

/* Endpoint addresses come from the host, not from a checked driver API.
   Reject nonexistent endpoints and directions before any LLD access.*/
if (recipient == USB_RTYPE_RECIPIENT_ENDPOINT) {
  chSysLock();
  if (((req[4] & 0x70U) != 0U) || (req[5] != 0U) ||
      (ep > USB_MAX_ENDPOINTS) || (self->epc[ep] == NULL) ||
      (in ?
       (self->epc[ep]->in_state == NULL) :
       (self->epc[ep]->out_state == NULL))) {
    chSysUnlock();
    usbEp0Stall(self);
    return MSG_OK;
  }
  chSysUnlock();
}

switch (type) {
case (uint32_t)USB_RTYPE_RECIPIENT_DEVICE |
     ((uint32_t)USB_REQ_GET_STATUS << 8):
  msg = usbEp0Reply(self, (const uint8_t *)&self->status, 2U);
  break;
case (uint32_t)USB_RTYPE_RECIPIENT_DEVICE |
     ((uint32_t)USB_REQ_CLEAR_FEATURE << 8):
  if (req[2] == USB_FEATURE_DEVICE_REMOTE_WAKEUP) {
    chSysLock();
    if (!ep0_is_current_i(self)) {
      chSysUnlock();
      return MSG_RESET;
    }
    self->status &= ~2U;
    chSysUnlock();
    msg = usbEp0Acknowledge(self);
  }
  else {
    usbEp0Stall(self);
  }
  break;
case (uint32_t)USB_RTYPE_RECIPIENT_DEVICE |
     ((uint32_t)USB_REQ_SET_FEATURE << 8):
  if (req[2] == USB_FEATURE_DEVICE_REMOTE_WAKEUP) {
    chSysLock();
    if (!ep0_is_current_i(self)) {
      chSysUnlock();
      return MSG_RESET;
    }
    self->status |= 2U;
    chSysUnlock();
    msg = usbEp0Acknowledge(self);
  }
  else {
    usbEp0Stall(self);
  }
  break;
case (uint32_t)USB_RTYPE_RECIPIENT_DEVICE |
     ((uint32_t)USB_REQ_SET_ADDRESS << 8):
  chSysLock();
  if (!ep0_is_current_i(self)) {
    chSysUnlock();
    return MSG_RESET;
  }
  if (self->state == USB_ACTIVE) {
    usb_unconfigure_device_i(self);
    if (self->state == USB_ERROR) {
      chSchRescheduleS();
      chSysUnlock();
      return HAL_RET_HW_FAILURE;
    }
  }
#if USB_SET_ADDRESS_MODE == USB_EARLY_SET_ADDRESS
  self->address = req[2];
  usb_lld_set_address(self);
#endif
  /* Commit before another SETUP or reset can replace the request state.*/
  self->ep0endcb = set_address;
  /* The unconfigure hooks can wake threads.*/
  chSchRescheduleS();
  chSysUnlock();
  msg = usbEp0Acknowledge(self);
  break;
case (uint32_t)USB_RTYPE_RECIPIENT_DEVICE |
     ((uint32_t)USB_REQ_GET_DESCRIPTOR << 8):
  if (self->binder == NULL) {
    usbEp0Stall(self);
    break;
  }
  dp = usbBinderGetDescriptor(self->binder, req[3],
                              req[2],
                              get_hword(&req[4]));
  if (dp != NULL) {
    msg = usbEp0Reply(self, dp->ud_string, dp->ud_size);
  }
  else {
    usbEp0Stall(self);
  }
  break;
case (uint32_t)USB_RTYPE_RECIPIENT_DEVICE |
     ((uint32_t)USB_REQ_GET_CONFIGURATION << 8):
  msg = usbEp0Reply(self, &self->configuration, 1U);
  break;
case (uint32_t)USB_RTYPE_RECIPIENT_DEVICE |
     ((uint32_t)USB_REQ_SET_CONFIGURATION << 8):
  chSysLock();
  if (self->state == USB_ERROR) {
    chSysUnlock();
    return HAL_RET_HW_FAILURE;
  }
  if (!ep0_is_current_i(self)) {
    chSysUnlock();
    return MSG_RESET;
  }
  if (self->state == USB_ACTIVE) {
    usb_unconfigure_device_i(self);
    if (self->state == USB_ERROR) {
      chSchRescheduleS();
      chSysUnlock();
      return HAL_RET_HW_FAILURE;
    }
  }
  if (req[2] != 0U) {
    self->configuration = req[2];
    self->state = USB_ACTIVE;
    if (self->binder != NULL) {
      self->svcconfigured = true;
      usbBinderConfigureI(self->binder);
    }
    if (self->state == USB_ERROR) {
      /* Failure inside the configure hooks, all of them returned and the
         services can be unconfigured now.*/
      usb_unconfigure_services_i(self);
      chSchRescheduleS();
      chSysUnlock();
      return HAL_RET_HW_FAILURE;
    }
    usb_post_events_i(self, USB_FLAGS_CONFIGURED);
  }
  /* Unconfigure and configure hooks can wake threads.*/
  chSchRescheduleS();
  chSysUnlock();
  msg = usbEp0Acknowledge(self);
  break;
case (uint32_t)USB_RTYPE_RECIPIENT_INTERFACE |
     ((uint32_t)USB_REQ_GET_STATUS << 8):
  msg = usbEp0Reply(self, zero_status, 2U);
  break;
case (uint32_t)USB_RTYPE_RECIPIENT_ENDPOINT |
     ((uint32_t)USB_REQ_GET_STATUS << 8):
  if (in) {
    switch (usb_lld_get_status_in(self, ep)) {
    case EP_STATUS_STALLED:
      msg = usbEp0Reply(self, halted_status, 2U);
      break;
    case EP_STATUS_ACTIVE:
      msg = usbEp0Reply(self, active_status, 2U);
      break;
    case EP_STATUS_DISABLED:
    default:
      usbEp0Stall(self);
      break;
    }
  }
  else {
    switch (usb_lld_get_status_out(self, ep)) {
    case EP_STATUS_STALLED:
      msg = usbEp0Reply(self, halted_status, 2U);
      break;
    case EP_STATUS_ACTIVE:
      msg = usbEp0Reply(self, active_status, 2U);
      break;
    case EP_STATUS_DISABLED:
    default:
      usbEp0Stall(self);
      break;
    }
  }
  break;
case (uint32_t)USB_RTYPE_RECIPIENT_ENDPOINT |
     ((uint32_t)USB_REQ_CLEAR_FEATURE << 8):
  if (req[2] == USB_FEATURE_ENDPOINT_HALT) {
    chSysLock();
    if (!ep0_is_current_i(self)) {
      chSysUnlock();
      return MSG_RESET;
    }
    /* The owning service can keep the halt, the request is acknowledged
       anyway.*/
    if ((ep != 0U) &&
        ((self->binder == NULL) ||
         !usbBinderClearHaltI(self->binder, ep, in))) {
      if (in) {
        usb_lld_clear_in(self, ep);
      }
      else {
        usb_lld_clear_out(self, ep);
      }
      if (self->binder != NULL) {
        usbBinderHaltClearedI(self->binder, ep, in);
      }
    }
    /* The halt hooks can wake threads.*/
    chSchRescheduleS();
    chSysUnlock();
    msg = usbEp0Acknowledge(self);
  }
  else {
    usbEp0Stall(self);
  }
  break;
case (uint32_t)USB_RTYPE_RECIPIENT_ENDPOINT |
     ((uint32_t)USB_REQ_SET_FEATURE << 8):
  if (req[2] == USB_FEATURE_ENDPOINT_HALT) {
    chSysLock();
    if (!ep0_is_current_i(self)) {
      chSysUnlock();
      return MSG_RESET;
    }
    if (ep != 0U) {
      if (in) {
        usb_lld_stall_in(self, ep);
      }
      else {
        usb_lld_stall_out(self, ep);
      }
    }
    chSysUnlock();
    msg = usbEp0Acknowledge(self);
  }
  else {
    usbEp0Stall(self);
  }
  break;
default:
  *handledp = false;
  break;
}

return msg;

chDbgCheckClassI();
chDbgCheck((self != NULL) && (ep <= (usbep_t)USB_MAX_ENDPOINTS));

if (((self->receiving &
      (uint16_t)((unsigned)1U << (unsigned)ep))) != 0U) {
  return true;
}

usb_lld_stall_out(self, ep);
return false;

chDbgCheckClassI();
chDbgCheck((self != NULL) && (ep <= (usbep_t)USB_MAX_ENDPOINTS));

if (((self->transmitting &
      (uint16_t)((unsigned)1U << (unsigned)ep))) != 0U) {
  return true;
}

usb_lld_stall_in(self, ep);
return false;

usbeventflags_t flags;
syssts_t sts;

sts = chSysGetStatusAndLockX();
flags = self->events & mask;
self->events &= ~mask;
chSysRestoreStatusX(sts);

return flags;

msg_t msg;
unsigned i;

chDbgAssert(self->ep0thread == NULL, "EP0 waiter still pending");

if (config != NULL) {
  self->config = __usb_setcfg_impl(self, config);
  if (self->config == NULL) {
    return HAL_RET_CONFIG_ERROR;
  }
}

self->events        = (usbeventflags_t)0U;
self->transmitting  = 0U;
self->receiving     = 0U;
self->ep0state      = USB_EP0_STP_WAITING;
self->ep0next       = NULL;
self->ep0n          = 0U;
self->ep0endcb      = NULL;
/* Requests taken before are stale, the sequence is never reset.*/
self->ep0seq++;
self->ep0setup      = 0U;
self->ep0reset      = 0U;
self->status        = 0U;
self->address       = 0U;
self->configuration = 0U;
self->svcconfigured = false;
self->saved_state   = HAL_DRV_STATE_STOP;
for (i = 0U; i <= (unsigned)USB_MAX_ENDPOINTS; i++) {
  self->epc[i] = NULL;
}

msg = usb_lld_start(self);
if (msg != HAL_RET_SUCCESS) {
  self->config = NULL;
}

return msg;

hal_usb_binder_c *binderp;
unsigned i;

(void)prevstate;

usb_lld_stop(self);

/* Services are unconfigured and the waiters woken before unbinding, the
   EP0 worker can be inside a service request hook. EP0 has a waiter even
   when USB_USE_SYNCHRONIZATION is disabled.*/
chSysLock();
usb_unconfigure_services_i(self);
binderp = self->binder;
self->binder = NULL;
self->events        = (usbeventflags_t)0U;
self->transmitting  = 0U;
self->receiving     = 0U;
self->ep0state      = USB_EP0_STP_WAITING;
self->ep0next       = NULL;
self->ep0n          = 0U;
self->ep0endcb      = NULL;
/* Requests taken before are stale, the sequence is never reset.*/
self->ep0seq++;
self->ep0setup      = 0U;
self->ep0reset      = 0U;
self->status        = 0U;
self->address       = 0U;
self->configuration = 0U;
self->saved_state   = HAL_DRV_STATE_STOP;
chThdResumeI(&self->ep0thread, MSG_RESET);
for (i = 0U; i <= (unsigned)USB_MAX_ENDPOINTS; i++) {
#if USB_USE_SYNCHRONIZATION == TRUE
  if (self->epc[i] != NULL) {
    if (self->epc[i]->in_state != NULL) {
      chThdResumeI(&self->epc[i]->in_state->thread, MSG_RESET);
    }
    if (self->epc[i]->out_state != NULL) {
      chThdResumeI(&self->epc[i]->out_state->thread, MSG_RESET);
    }
  }
#endif
  self->epc[i] = NULL;
}
chSchRescheduleS();
chSysUnlock();

/* The unbind hooks are API functions and run outside the lock.*/
if (binderp != NULL) {
  usbBinderUnbind(binderp);
}

if ((self->state == USB_SELECTED) ||
    (self->state == USB_ACTIVE) ||
    (self->state == USB_SUSPENDED)) {
  return NULL;
}

return (const void *)usb_lld_setcfg(self,
                                    (const hal_usb_config_t *)config);

if ((self->state == USB_SELECTED) ||
    (self->state == USB_ACTIVE) ||
    (self->state == USB_SUSPENDED)) {
  return NULL;
}

return (const void *)usb_lld_selcfg(self, cfgnum);

