function.details:
The LLD must first disconnect the device and mask hardware
          interrupts. This helper releases waiters and posts the error event;
          it does not call service or endpoint callbacks.

function.implementation:
#if USB_USE_SYNCHRONIZATION == TRUE
unsigned i;
#endif

chDbgCheckClassI();
if (usbp->state == USB_ERROR) {
  return;
}
usbp->state = USB_ERROR;
usbp->transmitting = 0U;
usbp->receiving = 0U;
usbp->configuration = 0U;
usbp->ep0n = 0U;
usbp->ep0next = NULL;
usbp->ep0endcb = NULL;
usbp->ep0state = USB_EP0_ERROR;
usbp->ep0setup = 0U;
usbp->ep0reset = 0U;
usbp->ep0seq++;
chThdResumeI(&usbp->ep0thread, HAL_RET_HW_FAILURE);
#if USB_USE_SYNCHRONIZATION == TRUE
for (i = 0U; i <= (unsigned)USB_MAX_ENDPOINTS; i++) {
  if (usbp->epc[i] != NULL) {
    if (usbp->epc[i]->in_state != NULL) {
      chThdResumeI(&usbp->epc[i]->in_state->thread, HAL_RET_HW_FAILURE);
    }
    if (usbp->epc[i]->out_state != NULL) {
      chThdResumeI(&usbp->epc[i]->out_state->thread, HAL_RET_HW_FAILURE);
    }
  }
}
#endif
usbp->events |= USB_FLAGS_HW_FAILURE;

unsigned i;

/* Bus events must not undo the lifecycle transition made by drvStop().*/
if ((usbp->state == HAL_DRV_STATE_STOPPING) || (usbp->state == USB_ERROR)) {
  return;
}
usbp->state         = HAL_DRV_STATE_READY;
usbp->status        = 0U;
usbp->address       = 0U;
usbp->configuration = 0U;
usbp->ep0n          = 0U;
usbp->transmitting  = 0U;
usbp->receiving     = 0U;
for (i = 0U; i <= (unsigned)USB_MAX_ENDPOINTS; i++) {
#if USB_USE_SYNCHRONIZATION == TRUE
  if (usbp->epc[i] != NULL) {
    chSysLockFromISR();
    if (usbp->epc[i]->in_state != NULL) {
      chThdResumeI(&usbp->epc[i]->in_state->thread, MSG_RESET);
    }
    if (usbp->epc[i]->out_state != NULL) {
      chThdResumeI(&usbp->epc[i]->out_state->thread, MSG_RESET);
    }
    chSysUnlockFromISR();
  }
#endif
  usbp->epc[i] = NULL;
}

  usbp->ep0state = USB_EP0_STP_WAITING;
  usbp->ep0setup = 0U;
  usbp->ep0reset = 0U;
  usb_lld_reset(usbp);
  if (usbp->state == USB_ERROR) {
    return;
  }
  chSysLockFromISR();
  /* For the services a reset is also an unconfigure notification.*/
  usbp->svcconfigured = false;
  if (usbp->binder != NULL) {
    usbBinderResetI(usbp->binder);
  }
  ep0_signal_reset_i(usbp);
  chSysUnlockFromISR();
  _usb_isr_invoke_event_cb(usbp, USB_FLAGS_RESET);

if ((usbp->state != HAL_DRV_STATE_STOPPING) &&
    (usbp->state != USB_SUSPENDED) && (usbp->state != USB_ERROR)) {
#if USB_USE_SYNCHRONIZATION == TRUE
  unsigned i;
#endif

  usbp->saved_state = usbp->state;
  usbp->state = USB_SUSPENDED;
  _usb_isr_invoke_event_cb(usbp, USB_FLAGS_SUSPEND);
  usbp->transmitting = 0U;
  usbp->receiving = 0U;
#if USB_USE_SYNCHRONIZATION == TRUE
  for (i = 0U; i <= (unsigned)USB_MAX_ENDPOINTS; i++) {
    if (usbp->epc[i] != NULL) {
      chSysLockFromISR();
      if (usbp->epc[i]->in_state != NULL) {
        chThdResumeI(&usbp->epc[i]->in_state->thread, MSG_RESET);
      }
      if (usbp->epc[i]->out_state != NULL) {
        chThdResumeI(&usbp->epc[i]->out_state->thread, MSG_RESET);
      }
      chSysUnlockFromISR();
    }
  }
#endif
  chSysLockFromISR();
  if (usbp->binder != NULL) {
    usbBinderSuspendI(usbp->binder);
  }
  ep0_signal_reset_i(usbp);
  chSysUnlockFromISR();
}

if (usbp->state == USB_SUSPENDED) {
  usbp->state = usbp->saved_state;
  chSysLockFromISR();
  if (usbp->binder != NULL) {
    usbBinderWakeupI(usbp->binder);
  }
  chSysUnlockFromISR();
  _usb_isr_invoke_event_cb(usbp, USB_FLAGS_WAKEUP);
}

msg_t msg = MSG_OK;

chDbgAssert(ep == 0U, "EP not zero");

chSysLockFromISR();
if ((usbp->state == HAL_DRV_STATE_STARTING) ||
    (usbp->state == HAL_DRV_STATE_STOPPING)) {
  chSysUnlockFromISR();
  return;
}
if (usbp->ep0state != USB_EP0_STP_WAITING) {
  setup_reset_i(usbp);
  msg = MSG_RESET;
}
usbReadSetupI(usbp, 0U, usbp->setup);
ep0_signal_setup_i(usbp, msg);
chSysUnlockFromISR();

size_t max;

chDbgAssert(ep == 0U, "EP not zero");

switch (usbp->ep0state) {
case USB_EP0_IN_TX:
  max = (size_t)get_hword(&usbp->ep0req[6]);
  if ((usbp->ep0n < max) &&
      ((usbp->ep0n % usbp->epc[0]->in_maxsize) == 0U)) {
    chSysLockFromISR();
    usbStartTransmitI(usbp, 0U, NULL, 0U);
    chSysUnlockFromISR();
    usbp->ep0state = USB_EP0_IN_WAITING_TX0;
    return;
  }
  /* Falls through. */
case USB_EP0_IN_WAITING_TX0:
  usbp->ep0state = USB_EP0_OUT_WAITING_STS;
  chSysLockFromISR();
  usbStartReceiveI(usbp, 0U, NULL, 0U);
  chSysUnlockFromISR();
  return;
case USB_EP0_IN_SENDING_STS:
  if (usbp->ep0endcb != NULL) {
    usbp->ep0endcb(usbp);
  }
  chSysLockFromISR();
  setup_reset_i(usbp);
  ep0_resume_waiter_i(usbp, MSG_OK);
  chSysUnlockFromISR();
  return;
case USB_EP0_OUT_WAITING_STS:
  return;
case USB_EP0_ERROR:
  chSysLockFromISR();
  setup_error_i(usbp);
  ep0_signal_reset_i(usbp);
  chSysUnlockFromISR();
  return;
default:
  chDbgAssert(false, "EP0 state machine error");
}

chDbgAssert(ep == 0U, "EP not zero");

switch (usbp->ep0state) {
case USB_EP0_OUT_RX:
  usbp->ep0state = USB_EP0_IN_SENDING_STS;
  chSysLockFromISR();
  usbStartTransmitI(usbp, 0U, NULL, 0U);
  chSysUnlockFromISR();
  return;
case USB_EP0_OUT_WAITING_STS:
  /* A status stage carrying data is accepted as a zero size one.*/
  if (usbp->ep0endcb != NULL) {
    usbp->ep0endcb(usbp);
  }
  chSysLockFromISR();
  setup_reset_i(usbp);
  ep0_resume_waiter_i(usbp, MSG_OK);
  chSysUnlockFromISR();
  return;
case USB_EP0_IN_TX:
  return;
case USB_EP0_ERROR:
  chSysLockFromISR();
  setup_error_i(usbp);
  ep0_signal_reset_i(usbp);
  chSysUnlockFromISR();
  return;
default:
  chDbgAssert(false, "EP0 state machine error");
}

uint16_t hw;

hw  = (uint16_t)*p++;
hw |= (uint16_t)*p << 8U;

return hw;

unsigned abase, alimit, bbase, blimit;

if ((ap->if_count == 0U) || (bp->if_count == 0U)) {
  return false;
}

abase  = (unsigned)ap->if_base;
alimit = abase + (unsigned)ap->if_count;
bbase  = (unsigned)bp->if_base;
blimit = bbase + (unsigned)bp->if_count;

return (abase < blimit) && (bbase < alimit);

hal_usb_service_c *servicep;

for (servicep = binderp->services; servicep != NULL;
     servicep = servicep->next) {
  if (usbServiceOwnsInterfaceX(servicep, ifn)) {
    return servicep;
  }
}

return NULL;

hal_usb_service_c *servicep;

for (servicep = binderp->services; servicep != NULL;
     servicep = servicep->next) {
  if (in ? usbServiceOwnsInEndpointX(servicep, ep) :
           usbServiceOwnsOutEndpointX(servicep, ep)) {
    return servicep;
  }
}

return NULL;

if (usbbnd_if_conflict(ap, bp)) {
  return true;
}

/* The driver keeps one configuration per endpoint number, the directions
   are not owned separately.*/
return ((ap->in_ep_mask | ap->out_ep_mask) &
        (bp->in_ep_mask | bp->out_ep_mask)) != 0U;

chDbgCheckClassI();

if (usbp->state != USB_ERROR) {
  usbp->events |= flags;
}

chDbgCheckClassI();

if (usbp->svcconfigured) {
  usbp->svcconfigured = false;
  if (usbp->binder != NULL) {
    usbBinderUnconfigureI(usbp->binder);
  }
}

chDbgCheckClassI();

usbDisableEndpointsI(usbp);
usb_unconfigure_services_i(usbp);
if (usbp->state != USB_ERROR) {
  usbp->configuration = 0U;
  usbp->state = USB_SELECTED;
  usb_post_events_i(usbp, USB_FLAGS_UNCONFIGURED);
}

chDbgCheckClassI();

usbp->receiving &= ~1U;
usbp->transmitting &= ~1U;
usbp->ep0n = 0U;
usbp->ep0endcb = NULL;
usbp->ep0state = USB_EP0_STP_WAITING;

chDbgCheckClassI();

usb_lld_stall_in(usbp, 0U);
usb_lld_stall_out(usbp, 0U);
usb_post_events_i(usbp, USB_FLAGS_STALLED);
usbp->receiving &= ~1U;
usbp->transmitting &= ~1U;
usbp->ep0n = 0U;
usbp->ep0endcb = NULL;
usbp->ep0state = USB_EP0_ERROR;

usbp->ep0setup = 0U;
usbp->ep0reset = 1U;
usbp->ep0endcb = NULL;
usbp->ep0seq++;
ep0_resume_waiter_i(usbp, MSG_RESET);

usbp->ep0setup = 1U;
usbp->ep0reset = 0U;
usbp->ep0endcb = NULL;
usbp->ep0seq++;
ep0_resume_waiter_i(usbp, msg);

if ((usbp->state == HAL_DRV_STATE_UNINIT) ||
    (usbp->state == HAL_DRV_STATE_STOP) ||
    (usbp->state == HAL_DRV_STATE_STARTING) ||
    (usbp->state == HAL_DRV_STATE_STOPPING) ||
    (usbp->state == USB_ERROR)) {
  return false;
}

return usbp->ep0rseq == usbp->ep0seq;

chSysLockFromISR();
/* Bus events must not undo the lifecycle transition made by drvStop().*/
if ((usbp->state == HAL_DRV_STATE_READY) || (usbp->state == USB_SELECTED)) {
#if USB_SET_ADDRESS_MODE == USB_LATE_SET_ADDRESS
  usbp->address = usbp->ep0req[2];
  usb_lld_set_address(usbp);
#endif
  /* Address zero is the default state.*/
  usbp->state = (usbp->address != 0U) ? USB_SELECTED : HAL_DRV_STATE_READY;
  usb_post_events_i(usbp, USB_FLAGS_ADDRESS);
}
chSysUnlockFromISR();

msg_t msg;
size_t max;

chSysLock();
if (usbp->state == USB_ERROR) {
  chSysUnlock();
  return HAL_RET_HW_FAILURE;
}
if ((usbp->state == HAL_DRV_STATE_STOP) ||
    (usbp->state == HAL_DRV_STATE_STOPPING) ||
    (usbp->ep0rseq != usbp->ep0seq)) {
  chSysUnlock();
  return MSG_RESET;
}

max = (size_t)get_hword(&usbp->ep0req[6]);
if (n > max) {
  n = max;
}

usbp->ep0next = (uint8_t *)buf;
usbp->ep0n = n;
if (n != 0U) {
  usbp->ep0state = USB_EP0_IN_TX;
  usbStartTransmitI(usbp, 0U, buf, n);
}
else if (max != 0U) {
  /* Empty reply to a request with a data stage, a zero size packet is
     the data stage.*/
  usbp->ep0state = USB_EP0_IN_WAITING_TX0;
  usbStartTransmitI(usbp, 0U, NULL, 0U);
}
else {
  /* No data stage, the status stage is an IN transaction.*/
  usbp->ep0state = USB_EP0_IN_SENDING_STS;
  usbStartTransmitI(usbp, 0U, NULL, 0U);
}

msg = chThdSuspendTimeoutS(&usbp->ep0thread, TIME_INFINITE);
/* The wakeup records completion or abort. A later SETUP cannot undo a
   completed status stage, even if this thread has not run in between.*/
chSysUnlock();

return msg;

msg_t msg;
size_t max;

chSysLock();
if (usbp->state == USB_ERROR) {
  chSysUnlock();
  return HAL_RET_HW_FAILURE;
}
if ((usbp->state == HAL_DRV_STATE_STOP) ||
    (usbp->state == HAL_DRV_STATE_STOPPING) ||
    (usbp->ep0rseq != usbp->ep0seq)) {
  chSysUnlock();
  return MSG_RESET;
}

max = (size_t)get_hword(&usbp->ep0req[6]);
if (n < max) {
  /* The host would send more than the buffer holds.*/
  setup_error_i(usbp);
  chSysUnlock();
  return MSG_RESET;
}
n = max;

usbp->ep0next = buf;
usbp->ep0n = n;
if (n != 0U) {
  usbp->ep0state = USB_EP0_OUT_RX;
  usbStartReceiveI(usbp, 0U, buf, n);
}
else {
  usbp->ep0state = USB_EP0_IN_SENDING_STS;
  usbStartTransmitI(usbp, 0U, NULL, 0U);
}

msg = chThdSuspendTimeoutS(&usbp->ep0thread, TIME_INFINITE);
/* Preserve the result delivered before any subsequent SETUP or reset.*/
chSysUnlock();

return msg;

